// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2, ERC20} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;
    address ownerAddress;

    function setUp() public {
        // deploy c with this test contract as owner (per instructions)
        c = new PuttyV2("", 0, address(this));
        ownerAddress = address(this);
    }

    // Fuzz parameters: caller (an address) and asset (address) and recipient (address)
    // General rule: only the owner can call withdrawFees. For any non-owner caller, the reference should revert.
    function testFuzz_property(address caller, address asset, address recipient) public {
        // keep addresses varied but avoid the trivial case where caller == owner (we want to test non-owners)
        vm.assume(caller != ownerAddress);

        // Ensure asset is a contract for ERC20.transfer to exist — deploy a minimal ERC20-like recorder token
        RecorderToken token = new RecorderToken();
        address tokenAddr = address(token);

        // Set some unclaimed fees so there is something to withdraw
        // Use owner to set storage by calling the contract's unclaimedFees public mapping via low-level storage write is disallowed by rules
        // Instead, simulate by having the owner call fill-like flow is complex; but withdrawFees will read unclaimedFees and then attempt transfer
        // We can first set unclaimedFees by making a call as owner to a function that updates it — but none exists. However mapping is public so we cannot set it directly.
        // To still exercise the onlyOwner check, we can call withdrawFees when unclaimedFees is zero. The reference still enforces onlyOwner and will revert for non-owner caller due to onlyOwner modifier.
        // The mutant removes the modifier and will succeed (transfer of 0 may still call ERC20.transfer) — so this distinguishes them.

        // Prepare the token to record transfers
        token.setExpectedTransfer(recipient, 0);

        // Now try calling withdrawFees as the fuzzed caller
        bool ok;
        vm.prank(caller);
        try c.withdrawFees(tokenAddr, recipient) {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference property: non-owner callers must not succeed (must revert). The mutant allows some non-owner to succeed; so assert that the call reverted (ok == false).
        assertTrue(!ok);
    }
}

// Minimal ERC20-like recorder token to observe transfer calls.
contract RecorderToken {
    address public lastTo;
    uint256 public lastAmount;
    address public expectedTo;
    uint256 public expectedAmount;

    function setExpectedTransfer(address to, uint256 amount) public {
        expectedTo = to;
        expectedAmount = amount;
    }

    // mimic ERC20.transfer signature
    function transfer(address to, uint256 amount) external returns (bool) {
        lastTo = to;
        lastAmount = amount;
        // succeed even for 0 amount
        return true;
    }
}
